#include <Arduino.h>
#include "pins.h"
#include <Wire.h>
#include <SPI.h>
#include <Adafruit_BME280.h>
#include <GxEPD2_BW.h>

Adafruit_BME280 bme;

void setup() {
  Serial.begin(115200);
  Wire.begin(I2C0_SDA, I2C0_SCL);
  SPI.begin(SPI0_SCK, SPI0_MISO, SPI0_MOSI);
  bme.begin(0x76);
  pinMode(BUTTON_1_SW, INPUT_PULLUP);
  pinMode(BUTTON_2_SW, INPUT_PULLUP);
  pinMode(BUTTON_3_SW, INPUT_PULLUP);
  pinMode(DISPLAY_BUSY, OUTPUT);
  pinMode(DISPLAY_CS, OUTPUT);
  pinMode(DISPLAY_DC, OUTPUT);
  pinMode(DISPLAY_RST, OUTPUT);
  Serial.println("boot ok");
}

void loop() {
  Serial.printf("T=%.1fC RH=%.0f%%\n", bme.readTemperature(), bme.readHumidity());
  delay(1000);
}
